import{_ as a,I as t,g as r,j as o}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Quick Start","description":"First steps in OmniCraft ERP. Basic setup, migrating balances, and data security principles.","frontmatter":{"title":"Quick Start","description":"First steps in OmniCraft ERP. Basic setup, migrating balances, and data security principles.","order":3},"headers":[],"relativePath":"docs/getting-started.md","filePath":"docs/getting-started.md"}'),s={name:"docs/getting-started.md"};function n(i,e,l,c,u,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>This page will guide you through the process of setting up OmniCraft ERP on your first run and seamlessly migrating data from your previous records (notebooks, Excel spreadsheets, or other software).</p><hr><h2 id="🌍-language-and-data-security" tabindex="-1">🌍 Language and Data Security <a class="header-anchor" href="#🌍-language-and-data-security" aria-label="Permalink to &quot;🌍 Language and Data Security&quot;">​</a></h2><p><strong>Localization:</strong> The program supports multiple languages and automatically detects your operating system&#39;s language on the first launch. You can always change it manually: select <strong>File ➔ Program Settings</strong> in the top menu, choose your preferred language, and restart the application.</p><p><strong>Data Security:</strong> Your data belongs entirely to you. We <strong>do not collect, store, or process your personal data or your business records</strong>. The application does not require any registration, email addresses, or phone numbers.</p><div class="info custom-block"><p class="custom-block-title">About Data Integrity and Backups</p><p>We make every effort to minimize data risks: the program features modern data protection mechanisms, the database runs in WAL mode (protecting against power failures), and it generates automatic background backups.</p><p>However, no system can guarantee data integrity with absolute certainty—data loss may still occur due to OS system failures, malicious software, hard drive wear, or other external causes. Maintaining backup copies remains your responsibility.</p><p>We highly recommend occasionally creating manual backups: <strong>File ➔ Export Data</strong>. The primary binary backup (<code>.db</code>) saves your entire system. However, as an extra safety measure, we recommend exporting your data in the second format as well—«Tables of the active workspace (.zip with CSV)». If the binary database file ever suffers minor corruption from drive failures and fails to load, you will have a fallback restoration option.</p></div><hr><h2 id="🚚-migrating-data-from-previous-records" tabindex="-1">🚚 Migrating Data from Previous Records <a class="header-anchor" href="#🚚-migrating-data-from-previous-records" aria-label="Permalink to &quot;🚚 Migrating Data from Previous Records&quot;">​</a></h2><p>If you are transitioning to OmniCraft ERP from another system, you do not need to manually log every past sale from previous years. You can migrate your current &quot;snapshot&quot; of the business in two simple steps.</p><h3 id="step-1-enter-current-assets-and-materials" tabindex="-1">Step 1. Enter Current Assets and Materials <a class="header-anchor" href="#step-1-enter-current-assets-and-materials" aria-label="Permalink to &quot;Step 1. Enter Current Assets and Materials&quot;">​</a></h3><ol><li>Open the <strong>Workshop</strong> tab and enter all your current equipment and tools at their original purchase price.</li><li>Open the <strong>Materials</strong> tab and enter the actual physical balances of raw materials (for example, leather, hardware, glue, or clay) currently on your shelves.</li></ol><p><em>What happens:</em> The program will place these values on the Workshop Balance Sheet. In doing so, it will automatically record the purchase transactions in your Cash Flow Ledger. At this stage, your Cash Flow balance will logically show a deep negative value—representing the historical volume of your personal investments to get the business running.</p><h3 id="step-2-record-initial-finances-cash-flow-and-capital" tabindex="-1">Step 2. Record Initial Finances (Cash Flow and Capital) <a class="header-anchor" href="#step-2-record-initial-finances-cash-flow-and-capital" aria-label="Permalink to &quot;Step 2. Record Initial Finances (Cash Flow and Capital)&quot;">​</a></h3><p>OmniCraft ERP operates under a <strong>mixed finances</strong> model by default. This means a negative balance in your Cash Flow Ledger is completely normal: it transparently reflects the volume of your personal historical investments made into machinery, tools, and raw materials during Step 1.</p><p>As your business begins generating revenue from finished goods sales, your Cash Flow balance will steadily increase and move into the positive, showing the full payback of your initial investments.</p><p><strong>If you wish to separate personal funds and business funds (set an initial cash balance):</strong></p><ol><li>If your machinery and tools were purchased long ago with personal savings and you do not want them to reduce your business cash balance, simply enable the <strong>&quot;Without Cash Flow expense&quot;</strong> option when adding them in the <strong>Workshop</strong> tab. The assets will be placed on your Balance Sheet under Capital without creating an expense in Cash Flow.</li><li>If you already have physical cash or a balance on a dedicated business account (e.g., $1,000), switch to the <strong>Cash Flow</strong> tab and use the <strong>&quot;Record Other Transactions&quot;</strong> form: <ul><li><strong>Transaction Type:</strong> Non-Operating Income;</li><li><strong>Category:</strong> Other;</li><li><strong>Amount:</strong> Your actual starting cash balance;</li><li><strong>Comment:</strong> <em>“Starting cash balance upon program launch”</em>.</li></ul></li></ol><p>That&#39;s it! Your database is configured, the calculations are synchronized, and both your Balance Sheet and Cash Flow Ledger reflect your true business reality without unnecessary friction.</p><hr><h2 id="🚀-base-pricing-settings" tabindex="-1">🚀 Base Pricing Settings <a class="header-anchor" href="#🚀-base-pricing-settings" aria-label="Permalink to &quot;🚀 Base Pricing Settings&quot;">​</a></h2><p>Before you proceed to create products (the <strong>Calculator</strong> tab), it is important to set your workshop&#39;s financial guidelines. Go to the <strong>Settings</strong> tab and set three primary parameters:</p><h3 id="_1-master-hourly-rate-currency-hour" tabindex="-1">1. Master Hourly Rate (Currency/Hour) <a class="header-anchor" href="#_1-master-hourly-rate-currency-hour" aria-label="Permalink to &quot;1. Master Hourly Rate (Currency/Hour)&quot;">​</a></h3><p>This is the cost of one hour of the master&#39;s labor.</p><ul><li><strong>If you hire assistants:</strong> Enter their average hourly wage here. The program will treat this money as a direct expense and factor it strictly into the cost price.</li><li><strong>If you work for yourself (solo artisan):</strong> You can set the rate to <code>0</code>. In this case, you won&#39;t have to make extra transactions to pay a &quot;salary&quot; to yourself. However, keep in mind: if your labor rate is zero, the value of your labor must be factored into your <em>global markup</em> percentage.</li></ul><h3 id="_2-global-markup" tabindex="-1">2. Global Markup (%) <a class="header-anchor" href="#_2-global-markup" aria-label="Permalink to &quot;2. Global Markup (%)&quot;">​</a></h3><p>This is your margin multiplier. The program automatically applies this percentage to the net cost price of an item (materials + labor + overhead costs) to calculate the <strong>Recommended Retail Price</strong> for you.</p><h3 id="_3-overhead-expenses-global-norms" tabindex="-1">3. Overhead Expenses (Global Norms) <a class="header-anchor" href="#_3-overhead-expenses-global-norms" aria-label="Permalink to &quot;3. Overhead Expenses (Global Norms)&quot;">​</a></h3><p>Overheads are the indirect costs of running your workshop: electricity, rent, consumables, or software. In Settings, you establish their baseline level. They can be of two types:</p><ul><li><strong>Percentage (%):</strong> Calculated as a percentage of the item&#39;s raw cost (materials and labor).</li><li><strong>Fixed (Currency):</strong> A flat monetary sum added to each produced item.</li></ul><p><strong>Customizing Within Recipes:</strong> You won&#39;t have to change your global settings every time different products have different manufacturing costs. When creating a recipe for a specific item in the <strong>Calculator</strong>, the program will offer you a smart panel of multipliers:</p><ul><li>If a product consumes twice as much electricity and glue, simply set its overhead coefficient to <code>2.0</code> (the program will multiply the global norm by two).</li><li>If a simple keychain does not require heavy machinery at all, set the coefficient to <code>0</code>, and these overhead costs will not be factored into its cost price.</li></ul><p>Once you have configured these parameters, your system is fully ready. You can now switch to the <strong>Calculator</strong> tab and create your first product recipes.</p>',33)])])}const g=a(s,[["render",n]]);export{p as __pageData,g as default};
